import { readFile, writeFile } from "node:fs/promises";
const root = new URL("../", import.meta.url);
const sources = await Promise.all(["language.js", "language-ui.js"].map(file => readFile(new URL(file, root), "utf8")));
await writeFile(new URL("page-language.js", root),
  "// Generated by scripts/build-page-language.mjs from language.js and language-ui.js.\n" + sources.join("\n"));
